import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const processRef = process as unknown as {
  exit: (code: number) => never;
  argv: readonly string[];
};

const USAGE = 'usage: inline-inertia.ts <example-directory>';

const GENERATED =
  '// Generated by scripts/inline-inertia.ts from inertia/root.html and the Vite build. ' +
  'Do not edit.\n';

interface ManifestEntry {
  readonly css?: readonly string[];
  readonly file: string;
}

/**
 * A Vercel Function ships only the modules it imports, so the root view and the built client are
 * turned into one module the application imports instead of files it reads at run time.
 */
async function inlineInertia(directory: string): Promise<void> {
  const root = path.resolve(directory);
  const client = path.join(root, 'dist', 'inertia', 'client');
  const [html, manifest] = await Promise.all([
    readFile(path.join(root, 'inertia', 'root.html'), 'utf8'),
    readFile(path.join(client, '.vite', 'manifest.json'), 'utf8'),
  ]);

  const entry: ManifestEntry = JSON.parse(manifest)['inertia/app.tsx'];
  const read = (file: string): Promise<string> => readFile(path.join(client, file), 'utf8');
  const styles = await Promise.all((entry.css ?? []).map((file) => read(file)));
  const source = await read(entry.file);
  const script = source.replaceAll('</script', String.raw`<\/script`);

  const assets = [
    ...styles.map((css) => `<style>${css}</style>`),
    `<script type="module">${script}</script>`,
  ].join('\n');

  const body = `${GENERATED}export const ROOT_VIEW = ${JSON.stringify(
    // A function replacement: the bundle contains `$&`/`$'` and `replace` would expand them.
    html.replace('@inertiaHead', '').replace("@vite('inertia/app.tsx')", () => assets),
  )};\n`;

  await writeFile(path.join(root, 'src', 'inertia.generated.ts'), body);
}

const isMain = Reflect.get(import.meta, 'main');
if (isMain) {
  const args = processRef.argv.slice(2);
  const [directory] = args;
  if (directory === undefined) {
    console.error(USAGE);
    processRef.exit(1);
    throw new Error(USAGE);
  }
  await inlineInertia(directory);
}

export { inlineInertia };
